//! Type-safe Font Awesome icon references.
//!
//! `iced_font_awesome` takes icon names as strings and silently renders a `?`
//! glyph for an unknown name, so a slug typo stays invisible until you notice
//! it on screen. Instead, the [`Icon`] enum is code-generated by `build.rs`
//! straight from `iced_font_awesome`'s own bundled metadata — one variant per
//! solid icon, from the same source it renders with. The rest of the app names
//! icons by their Rust identifier (`Icon::Foo`), so a reference to an icon that
//! does not exist fails to compile, and no slug string appears outside the
//! generated table.

use iced::widget::text::Catalog;
use iced_font_awesome::{Icon as FaIcon, fa_icon_brands, fa_icon_solid};

// Defines `pub enum Icon { .. }`, `Icon::name()`, and `Icon::is_brand()`. See
// `build.rs`.
include!(concat!(env!("OUT_DIR"), "/icons.rs"));

impl Icon {
    /// A widget for this icon in its own face — solid Free for most, the Brands
    /// face for brand-only glyphs — ready to `.size(..).color(..)`.
    pub fn solid<'a, Theme: Catalog>(self) -> FaIcon<'a, Theme> {
        if self.is_brand() {
            fa_icon_brands(self.name())
        } else {
            fa_icon_solid(self.name())
        }
    }
}
